  for (const chapter of [2, 3, 4, 0]) {
    await page.locator(`[data-cinema-jump="${chapter}"]`).click()
    await page.waitForFunction((index) =>
      document.querySelector(`[data-cinema-panel="${index}"]`)?.hasAttribute('data-active'), chapter)
    await page.waitForTimeout(500)
    const bounds = await page.evaluate(() => {
      const panel = document.querySelector('[data-cinema-panel][data-active]').getBoundingClientRect()
      const controls = document.querySelector('.lmm-core-steps').getBoundingClientRect()
      const stage = document.querySelector('[data-cinema-inner]').getBoundingClientRect()
      return { top: panel.top, bottom: panel.bottom, controlTop: controls.top, stageTop: stage.top }
    })
    assert.ok(bounds.bottom < bounds.controlTop, `${name}: chapter ${chapter} covers navigation`)
    assert.ok(bounds.top >= bounds.stageTop, `${name}: chapter ${chapter} clips above stage`)
  }
} else {
  const panels = await page.locator('[data-cinema-panel]').evaluateAll((elements) =>
    elements.map((panel) => ({ inert: panel.inert, visible: getComputedStyle(panel).visibility })))
  assert.ok(panels.every((panel) => !panel.inert && panel.visible === 'visible'),
    `${name}: static story must keep every chapter accessible`)

