test('homepage reserves separate grid rows for copy and navigation', () => {
  assert.match(css, /grid-template-rows: minmax\(0, 1fr\) auto;/)
  assert.match(css, /grid-template-rows: minmax\(0, 1fr\) auto auto;/)
  assert.match(css, /\.lmm-core-steps \{\s*grid-area: 2 \/ 2;/)
  assert.match(css, /grid-area: 3 \/ 1;/)
  assert.doesNotMatch(css, /(?:340svh|160rem|120rem)/)
})

test('short phones expose the complete static story instead of clipped controls', () => {
  assert.match(css, /\(max-width: 680px\) and \(max-height: 700px\)/)
  assert.match(motion, /window\.innerWidth > 680 \|\| window\.innerHeight > 700/)
})

test('connection controls use one accessible segmented group without new ornament dependencies', () => {
  assert.match(landingSource, /className='lmm-connection-method'/)
  assert.match(landingSource, /aria-pressed=\{connectionMethod === 'oauth'\}/)
  assert.match(landingSource, /aria-pressed=\{connectionMethod === 'api-key'\}/)
  assert.match(css, /\.lmm-connection-method \[aria-pressed='true'\]/)
  assert.doesNotMatch(css, /\.lmm-(?:request-sample|sample-head|pi-art|cinema-caption)/)
})

display: grid;
grid-template-columns: 54% 43% 3%;
grid-template-rows: minmax(0, 1fr) auto;
height: calc(100svh - 12rem);

grid-area: 1 / 2;
align-self: center;
position: relative;
width: 100%;

width: min(calc(100% - 2 * var(--home-gutter)), 76rem);
margin: 1.5rem auto 0;
padding: 1.2rem 0;
border-block: 1px solid var(--home-rule);

display: flex;
align-items: baseline;
justify-content: space-between;
flex-wrap: wrap;
gap: 1rem 2rem;

.lmm-connection-method {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  width: fit-content;
  max-width: 100%;
  margin-top: 1.75rem;
  padding: 0.3rem;
  border: 1px solid var(--home-rule);
  border-radius: 1.75rem;
}
.lmm-connection-method [data-slot='button'] {
  min-height: 2.75rem;
  border: 0;
  border-radius: 1.5rem;
  padding-inline: 1rem;
  background: transparent;
  color: var(--muted-foreground);
  box-shadow: none;
  font-size: 0.8rem;
  white-space: normal;
}
.lmm-connection-method [aria-pressed='true'] {
  background: var(--foreground);
  color: var(--background);
}

border: 1px solid var(--home-rule);
border-radius: 0.65rem;
background: color-mix(in oklch, var(--foreground) 2%, transparent);

border: 0;
border-bottom: 1px solid var(--home-rule);
border-radius: 0;
background: transparent;

font-family: var(--font-body);
font-size: clamp(1.75rem, 3vw, 2.5rem);
font-weight: 500;
line-height: 1.2;

min-height: 11rem;
padding: 1.5rem 0 0;
border-left: 0;
border-top: 1px solid var(--home-rule);

grid-template-columns: minmax(0, 1fr);
grid-template-rows: minmax(0, 1fr) auto auto;
